/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 3) {
    const m = lines[0] - 0;
    const arr = lines[1].split(" ").map((ele) => Number(ele));
    const n = lines[2] - 0;
    console.log(getResult(m, arr, n));
    lines.length = 0;
  }
});

function getResult(m, arr, n) {
  const set = new Set();

  for (let val of arr) {
    if (val < 0 || val > 1000) return -1;
    set.add(val);
  }

  if (set.size < n * 2) {
    return -1;
  }

  arr = [...set].sort((a, b) => a - b);

  let l = 0;
  let r = arr.length - 1;
  let ans = 0;

  while (n > 0) {
    ans += arr[l] + arr[r];
    l++;
    r--;
    n--;
  }

  return ans;
}
